#include <stdint.h>

/* Leaky: a branch on a secret bit. */
uint32_t select_branch(uint32_t bit, uint32_t a, uint32_t b) {
    if (bit) return a;
    return b;
}

/* Branchless: turn the bit into an all-ones or all-zeros mask. */
uint32_t ct_select(uint32_t bit, uint32_t a, uint32_t b) {
    uint32_t mask = 0u - bit;            /* 1 gives 0xFFFFFFFF, 0 gives 0 */
    return (a & mask) | (b & ~mask);
}

/* Constant-time lookup: touch every entry, keep only the wanted one. */
uint32_t ct_lookup(const uint32_t *table, uint32_t n, uint32_t idx) {
    uint32_t result = 0;
    for (uint32_t i = 0; i < n; i++) {
        uint32_t eq = (uint32_t)((((uint64_t)(i ^ idx)) - 1) >> 63); /* 1 if i == idx */
        result |= table[i] & (0u - eq);
    }
    return result;
}

uint32_t ct_select(uint32_t bit, uint32_t a, uint32_t b) {
    uint32_t mask = 0u - bit;
    uint32_t keep_a = a & mask;
    uint32_t keep_b = b & ~mask;
    return keep_a | keep_b;
}

