# Toy RSA (p=61, q=53). Real keys are 2048+ bits; the logic is the same.
p, q, e, d = 61, 53, 17, 2753
n = p * q
dp, dq, q_inv = d % (p - 1), d % (q - 1), pow(q, -1, p)

def sign_crt(m, glitch=False):
    sp = pow(m, dp, p)                 # half the work mod p
    sq = pow(m, dq, q)                 # half the work mod q
    if glitch:
        sp = (sp + 1) % p              # simulate a fault in one half
    return sq + q * ((q_inv * (sp - sq)) % p)

def sign_checked(m, glitch=False):
    s = sign_crt(m, glitch)
    if pow(s, e, n) != m:              # verify with the public key first
        raise RuntimeError("fault detected: signature withheld")
    return s

print("normal :", sign_checked(65))
try:
    print("glitch :", sign_checked(65, glitch=True))
except RuntimeError as err:
    print("glitch :", err)
